char* letter_grade(long long score) {
    char g;
    if (score >= 90)      g = 'A';
    else if (score >= 80) g = 'B';   // already known: score < 90
    else if (score >= 70) g = 'C';
    else if (score >= 60) g = 'D';
    else                  g = 'F';
    // A one-character C string: the letter plus the '\0' terminator.
    char* out = malloc(2);
    out[0] = g;
    out[1] = '\0';
    return out;
}

