bool is_anagram(char* s, char* t) {
    size_t n = strlen(s), m = strlen(t);
    if (n != m) return false;
    int count[26] = {0};                 /* zero-initialise all 26 counters */
    for (size_t i = 0; i < n; i++) {
        count[s[i] - 'a']++;
        count[t[i] - 'a']--;             /* same length, so one loop handles both */
    }
    for (int k = 0; k < 26; k++)
        if (count[k] != 0) return false;
    return true;
}

