bool is_subsequence(char* s, char* t) {
    /* Walk t with a pointer; advance s only on a match. Stop early if s is used up. */
    while (*s && *t) {
        if (*s == *t) s++;
        t++;
    }
    return *s == '\0';          /* reached s's terminator => everything matched */
}

