string reverseWords(string s) {
    // istringstream >> word skips any amount of whitespace: a ready-made tokenizer.
    istringstream in(s);
    vector<string> words;
    string word;
    while (in >> word) words.push_back(word);
    string out;
    for (auto it = words.rbegin(); it != words.rend(); ++it) {
        if (!out.empty()) out += ' ';
        out += *it;
    }
    return out;
}

