    long long value = 0;
    while (i < n && isdigit((unsigned char)s[i])) {
        value = value * 10 + (s[i++] - '0');
        if (value > (1LL << 31)) break;              // will clamp anyway
    }
    value *= sign;
    return clamp(value, (long long)INT_MIN, (long long)INT_MAX);   // C++17 <algorithm>
}

