vector<vector<long long>> rotateImage(vector<vector<long long>>& matrix) {
    int n = matrix.size();
    for (int r = 0; r < n; r++)
        for (int c = r + 1; c < n; c++)
            swap(matrix[r][c], matrix[c][r]);     // transpose
    for (auto& row : matrix) reverse(row.begin(), row.end());  // mirror
    return matrix;
}

