pub fn rotate_image(mut matrix: Vec<Vec<i64>>) -> Vec<Vec<i64>> {
    let n = matrix.len();
    for r in 0..n {
        for c in r + 1..n {
            // Two different rows: swap via a temporary (can't borrow both mutably).
            let t = matrix[r][c];
            matrix[r][c] = matrix[c][r];
            matrix[c][r] = t;
        }
    }
    for row in matrix.iter_mut() {
        row.reverse();
    }
    matrix
}

