        auto b = toLetter.find(words[i]);
        if (a != toWord.end() && a->second != words[i]) return false;
        if (b != toLetter.end() && b->second != c) return false;
        toWord[c] = words[i];
        toLetter[words[i]] = c;
    }
    return true;
}

