    enum { OFFSET = 1000, K = 2001 };
    int* count = calloc(K, sizeof(int));          // calloc zero-fills; malloc doesn't
    for (int i = 0; i < numsSize; i++) count[nums[i] + OFFSET]++;
    long long* out = malloc(sizeof(long long) * (numsSize > 0 ? numsSize : 1));
    int k = 0;
