    vector<int> cnt(K);                     // value-initialised to zeros
    for (long long v : nums) cnt[v + OFFSET]++;
    vector<long long> out;
    out.reserve(nums.size());
    for (int idx = 0; idx < K; idx++)
        out.insert(out.end(), cnt[idx], idx - OFFSET);   // cnt[idx] copies
    return out;
}

