use std::cmp::Reverse;
use std::collections::BinaryHeap;

pub fn find_kth_largest(nums: Vec<i64>, k: i64) -> i64 {
    // BinaryHeap is a max-heap; wrapping values in Reverse turns it into a min-heap.
    let mut heap = BinaryHeap::new();
    for x in nums {
        heap.push(Reverse(x));
        if heap.len() as i64 > k {
            heap.pop();
        }
    }
    heap.peek().unwrap().0
}

