bool isValidParentheses(string s) {
    string st;                         // std::string works fine as a char stack
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') { st.push_back(c); continue; }
        char want = c == ')' ? '(' : c == ']' ? '[' : '{';
        if (st.empty() || st.back() != want) return false;
        st.pop_back();
    }
    return st.empty();
}

