pub fn is_valid_parentheses(s: String) -> bool {
    let mut st: Vec<u8> = Vec::new();
    for c in s.bytes() {
        let want = match c {
            b')' => b'(',
            b']' => b'[',
            b'}' => b'{',
            _ => { st.push(c); continue; }
        };
        // pop() returns None on an empty stack, which also fails the comparison.
        if st.pop() != Some(want) {
            return false;
        }
    }
    st.is_empty()
}

