def min_stack(ops, vals):
    class MinStack:
        def __init__(self):
            # Each entry is (value, minimum of this entry and everything below it).
            # Popping an entry automatically "restores" the previous minimum,
            # because the entry below remembers it.
            self.st = []

        def push(self, x):
            m = min(x, self.st[-1][1]) if self.st else x
            self.st.append((x, m))

        def pop(self):
            self.st.pop()

        def top(self):
            return self.st[-1][0]

        def get_min(self):
            return self.st[-1][1]

    s = MinStack()
    out = []
    # Replay the operations; only top/getMin produce output.
    for op, v in zip(ops, vals):
        if op == "push":
            s.push(v)
        elif op == "pop":
            s.pop()
        elif op == "top":
            out.append(s.top())
        else:  # "getMin"
            out.append(s.get_min())
    return out

