def queue_via_stacks(ops, vals):
    class MyQueue:
        def __init__(self):
            self.inbox = []     # newest on top; receives every push
            self.outbox = []    # oldest on top; serves pop/peek

        def _shift(self):
            # Pour only when outbox is empty: its contents are older than anything
            # in inbox, so pouring on top of them would break FIFO order.
            # Each element is moved at most once in its lifetime -> amortised O(1).
            if not self.outbox:
                while self.inbox:
                    self.outbox.append(self.inbox.pop())

        def push(self, x):
            self.inbox.append(x)

        def pop(self):
            self._shift()
            return self.outbox.pop()

        def peek(self):
            self._shift()
            return self.outbox[-1]

        def empty(self):
            return not self.inbox and not self.outbox

    q = MyQueue()
    out = []
    for op, v in zip(ops, vals):
        if op == "push":
            q.push(v)
        elif op == "pop":
            out.append(q.pop())
        elif op == "peek":
            out.append(q.peek())
        else:  # "empty"
            out.append(1 if q.empty() else 0)
    return out

