    let n = temperatures.len();
    let mut ans = vec![0i64; n];
    let mut st: Vec<usize> = Vec::new();
    for i in 0..n {
        // while-let pops as long as the top is strictly cooler than today
        while let Some(&j) = st.last() {
            if temperatures[j] >= temperatures[i] {
                break;
            }
            st.pop();
            ans[j] = (i - j) as i64;
        }
        st.push(i);
    }
    ans
}

