    vector<long long> ans(n, -1);
    vector<int> st;
    for (int i = 0; i < 2 * n; i++) {
        long long x = nums[i % n];
        while (!st.empty() && nums[st.back()] < x) {
            ans[st.back()] = x;
            st.pop_back();
