static void walk(struct TreeNode* n, long long** out, int* len, int* cap) {
    if (!n) return;
    walk(n->left, out, len, cap);
    if (*len == *cap) {                      /* grow the output like a vector */
        *cap *= 2;
        *out = realloc(*out, sizeof(long long) * (size_t)*cap);
    }
    (*out)[(*len)++] = n->val;
    walk(n->right, out, len, cap);
