    if (!n) return 0;
    long long l = check(n->left);
    if (l < 0) return -1;
    long long r = check(n->right);
    if (r < 0) return -1;
    if (l - r > 1 || r - l > 1) return -1;
    return 1 + (l > r ? l : r);
}

bool is_balanced(struct TreeNode* root) {
    return check(root) >= 0;
}

