fn dfs(node: &Option<Rc<RefCell<TreeNode>>>, depth: usize, out: &mut Vec<i64>) {
    if let Some(rc) = node {
        let n = rc.borrow();
        if depth == out.len() { out.push(n.val); }   // first visit at this depth
        dfs(&n.right, depth + 1, out);               // right side first
        dfs(&n.left, depth + 1, out);
    }
}

