static long long gainOf(TreeNode* n, long long& best) {
    if (!n) return 0;
    long long l = max(0LL, gainOf(n->left, best));
    long long r = max(0LL, gainOf(n->right, best));
    best = max(best, n->val + l + r);
    return n->val + max(l, r);
}

