    let mut parent: Vec<usize> = (0..n).collect();
    let mut size = vec![1usize; n];
    let mut comps = n as i64;
    for e in &edges {
        let (mut a, mut b) = (find(&mut parent, e[0] as usize), find(&mut parent, e[1] as usize));
        if a == b { continue; }
        if size[a] < size[b] { std::mem::swap(&mut a, &mut b); }
        parent[b] = a;
        size[a] += size[b];
        comps -= 1;
    }
    comps
