        for f in &flights {
            let (u, v, p) = (f[0] as usize, f[1] as usize, f[2]);
            if best[u] != i64::MAX && best[u] + p < nxt[v] {
                nxt[v] = best[u] + p;
            }
        }
        best = nxt;
    }
    if best[dst as usize] == i64::MAX { -1 } else { best[dst as usize] }
