    vector<vector<int>> adj(n);
    for (auto& c : connections) { adj[c[0]].push_back(c[1]); adj[c[1]].push_back(c[0]); }
    vector<int> tin(n, -1), low(n, 0);
    int timer = 0;
    vector<vector<long long>> out;
    bridgeDfs(0, -1, adj, tin, low, timer, out);
    sort(out.begin(), out.end());
    return out;
}

