    vector<char> dp(n + 1, 0);          // vector<char>, not vector<bool>: plain bytes
    dp[0] = 1;
    for (int i = 1; i <= n; ++i)
        for (int j = max(0, i - (int)longest); j < i && !dp[i]; ++j)
            if (dp[j] && dict.count(s.substr(j, i - j))) dp[i] = 1;
    return dp[n];
}

