pub fn max_coins(nums: Vec<i64>) -> i64 {
    let mut a = vec![1i64];
    a.extend_from_slice(&nums);
    a.push(1);
    let m = a.len();
    let mut dp = vec![vec![0i64; m]; m];
    for gap in 2..m {
        for l in 0..m - gap {
            let r = l + gap;
            dp[l][r] = (l + 1..r)
                .map(|k| dp[l][k] + a[l] * a[k] * a[r] + dp[k][r])
                .max()
                .unwrap_or(0);
        }
    }
    dp[0][m - 1]
}

