bool isMatch(string s, string p) {
    int n = s.size(), m = p.size();
    vector<vector<char>> dp(n + 1, vector<char>(m + 1, 0));
    dp[n][m] = 1;
    for (int i = n; i >= 0; --i)
        for (int j = m - 1; j >= 0; --j) {
            bool first = i < n && (p[j] == s[i] || p[j] == '.');
            if (j + 1 < m && p[j + 1] == '*')
                dp[i][j] = dp[i][j + 2] || (first && dp[i + 1][j]);   // zero | one more
            else
                dp[i][j] = first && dp[i + 1][j + 1];
        }
    return dp[0][0];
}

