    int m = t.size();
    vector<long long> dp(m + 1, 0);
    dp[0] = 1;                                  // empty target: one way
    for (char ch : s)
        for (int j = m; j >= 1; --j)            // downward: each char of s used once
            if (t[j - 1] == ch) dp[j] += dp[j - 1];
    return dp[m];
}

