pub fn num_distinct(s: String, t: String) -> i64 {
    let (s, t) = (s.as_bytes(), t.as_bytes());
    let (n, m) = (s.len(), t.len());
    // Full 2-D table, dp[i][j] over prefixes.
    let mut dp = vec![vec![0i64; m + 1]; n + 1];
    for i in 0..=n {
        dp[i][0] = 1;
    }
    for i in 1..=n {
        for j in 1..=m {
            dp[i][j] = dp[i - 1][j];
            if s[i - 1] == t[j - 1] {
                dp[i][j] += dp[i - 1][j - 1];
            }
        }
    }
    dp[n][m]
}

