long long hamming_weight(long long n) {
    // Work on an unsigned copy: shifting/masking unsigned values is always well defined.
    unsigned long long x = (unsigned long long)n;
    long long count = 0;
    while (x) {
        x &= x - 1;   // clear the lowest set bit
        count++;
    }
    return count;
}

