// ESPresso has no bitwise operators, so peel bits off arithmetically:
// the lowest bit is n mod 2, and integer division by 2 shifts right.
fn hammingWeight(n) {
  var x = n
  var count = 0
  while x > 0 {
    count += x - (x / 2) * 2   // x mod 2 (no % operator in ESPresso)
    x = x / 2                  // drop the lowest bit
  }
  return count
}

