// Recursive divide and conquer: b^e = (b^(e/2))^2 * (b if e is odd).
long long modPowRec(long long b, long long e, long long m) {
    if (e == 0) return 1 % m;
    long long half = modPowRec(b, e / 2, m);
    long long sq = half * half % m;
    return (e & 1) ? sq * b % m : sq;
}
