type Mat = [[u64; 2]; 2];

fn mul(a: &Mat, b: &Mat) -> Mat {
    let mut r = [[0u64; 2]; 2];
    for i in 0..2 {
        for j in 0..2 {
            // two products < 1e18 each; their sum < 2e18 < u64::MAX
            r[i][j] = (a[i][0] * b[0][j] + a[i][1] * b[1][j]) % M;
