    let (mut res, mut base): (Mat, Mat) = ([[1, 0], [0, 1]], [[1, 1], [1, 0]]);
    let mut e = n as u64;
    while e > 0 {
        if e & 1 == 1 {
            res = mul(&res, &base);
        }
        base = mul(&base, &base);
        e >>= 1;
    }
    res[0][1] as i64
}

