pub fn range_sum_queries(nums: Vec<i64>, ops: Vec<String>, args: Vec<Vec<i64>>) -> Vec<i64> {
    let n = nums.len();
    let mut tree = vec![0i64; 2 * n];
    tree[n..].copy_from_slice(&nums);
    for i in (1..n).rev() {
        tree[i] = tree[2 * i] + tree[2 * i + 1];
    }
    let mut out = Vec::new();
    for (op, a) in ops.iter().zip(args.iter()) {
        if op == "update" {
            let mut i = a[0] as usize + n;
            tree[i] = a[1];
            while i > 1 {
                i /= 2;
                tree[i] = tree[2 * i] + tree[2 * i + 1];
            }
        } else {
            let (mut l, mut r) = (a[0] as usize + n, a[1] as usize + n + 1);
            let mut total = 0;
            while l < r {
                if l & 1 == 1 {
                    total += tree[l];
                    l += 1;
                }
                if r & 1 == 1 {
                    r -= 1;
                    total += tree[r];
                }
                l /= 2;
                r /= 2;
            }
            out.push(total);
        }
    }
    out
}

