pub fn find_all_occurrences(text: String, pattern: String) -> Vec<i64> {
    // Work on bytes: O(1) indexing, and the input is ASCII.
    let (t, p) = (text.as_bytes(), pattern.as_bytes());
    let m = p.len();
    let mut fail = vec![0usize; m];
    let mut k = 0;
    for i in 1..m {
        while k > 0 && p[i] != p[k] {
            k = fail[k - 1];
