long long shortestTour(vector<vector<long long>>& dist) {
    int n = dist.size();
    if (n == 1) return 0;
    const long long INF = LLONG_MAX / 4;
    int full = (1 << n) - 1;
    vector<vector<long long>> dp(1 << n, vector<long long>(n, INF));
    dp[1][0] = 0;
    for (int mask = 1; mask <= full; mask += 2)          // odd masks contain city 0
        for (int j = 0; j < n; j++) {
            long long cur = dp[mask][j];
            if (cur >= INF) continue;
            for (int k = 0; k < n; k++) {
                if (mask & (1 << k)) continue;
                int nxt = mask | (1 << k);
                dp[nxt][k] = min(dp[nxt][k], cur + dist[j][k]);
            }
        }
    long long best = INF;
    for (int j = 1; j < n; j++) best = min(best, dp[full][j] + dist[j][0]);
    return best;
}

