pub fn shortest_tour(dist: Vec<Vec<i64>>) -> i64 {
    let n = dist.len();
    if n == 1 {
        return 0;
    }
    const INF: i64 = i64::MAX / 4; // headroom: INF + cost never overflows
    let full = (1usize << n) - 1;
    let mut dp = vec![vec![INF; n]; 1 << n];
    dp[1][0] = 0;
    for mask in (1..=full).step_by(2) { // odd masks = contain city 0
        for j in 0..n {
            let cur = dp[mask][j];
            if cur >= INF {
                continue;
            }
            for k in 0..n {
                if mask & (1 << k) != 0 {
                    continue;
                }
                let nxt = mask | (1 << k);
                dp[nxt][k] = dp[nxt][k].min(cur + dist[j][k]);
            }
        }
    }
    (1..n).map(|j| dp[full][j] + dist[j][0]).min().unwrap()
}

