use std::collections::VecDeque;

pub fn max_flow(n: i64, edges: Vec<Vec<i64>>, source: i64, sink: i64) -> i64 {
    let n = n as usize;
    let (s, t) = (source as usize, sink as usize);
    let mut to: Vec<usize> = Vec::new();
    let mut cap: Vec<i64> = Vec::new();
    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); n];
    for e in &edges {
        let (u, v) = (e[0] as usize, e[1] as usize);
        adj[u].push(to.len()); to.push(v); cap.push(e[2]);
        adj[v].push(to.len()); to.push(u); cap.push(0);
    }
    let mut flow = 0;
    loop {
        // via[x] = Some(edge) used to reach x
        let mut via: Vec<Option<usize>> = vec![None; n];
        let mut seen = vec![false; n];
        seen[s] = true;
        let mut q = VecDeque::from([s]);
        while let Some(u) = q.pop_front() {
            if seen[t] { break; }
            for &e in &adj[u] {
                if cap[e] > 0 && !seen[to[e]] {
                    seen[to[e]] = true;
                    via[to[e]] = Some(e);
                    q.push_back(to[e]);
                }
            }
        }
        if !seen[t] {
            return flow;
        }
        let mut b = i64::MAX;
        let mut x = t;
        while x != s {
            let e = via[x].unwrap();
            b = b.min(cap[e]);
            x = to[e ^ 1];
        }
        x = t;
        while x != s {
            let e = via[x].unwrap();
            cap[e] -= b;
            cap[e ^ 1] += b;
            x = to[e ^ 1];
        }
        flow += b;
    }
}

