// Binary search on the answer. hi starts at 46340 so mid * mid can never
// exceed 46340^2 = 2147395600 < 2^31: no silent 32-bit wraparound.
fn isqrt(n) {
    var lo = 0
    var hi = 46340
    if n < hi { hi = n }
    while lo < hi {
        var mid = (lo + hi + 1) / 2     // round up so "lo = mid" always makes progress
        if mid * mid <= n {
            lo = mid
        } else {
            hi = mid - 1
        }
    }
    return lo
}

