// Counter-based debouncer, the same logic you'd run in a 1 ms timer interrupt.
fn countPresses(samples, k) {
    var state = 0
    var run = 0
    var presses = 0
    for var i in 0..len(samples) {
        if samples[i] == state {
            run = 0                 // agreement resets the streak
        } else {
            run += 1
            if run == k {           // stable for k ticks: accept the new level
                state = samples[i]
                run = 0
                if state == 1 { presses += 1 }
            }
        }
    }
    return presses
}

