    double s = accumulate(samples.begin(), samples.begin() + window, 0.0);
    double best = s;
    for (size_t i = window; i < samples.size(); i++) {
        s += samples[i] - samples[i - window];
        best = max(best, s);
    }
    return best / window;
}

