pub fn uart_fifo(capacity: i64, ops: &mut Vec<i64>) {
    let cap = capacity as usize;
    let mut buf = [0i64; 16];
    let (mut head, mut tail, mut count) = (0usize, 0usize, 0usize);
    for op in ops.iter_mut() {
        if *op >= 0 {
            if count == cap {
                *op = 0;
            } else {
                buf[tail] = *op;
                tail = (tail + 1) % cap;
                count += 1;
                *op = 1;
            }
        } else if count == 0 {
            *op = -1;
        } else {
            *op = buf[head];
            head = (head + 1) % cap;
            count -= 1;
        }
    }
}

