// No bit operators and no %: shifts by 4 bits are "/ 16" and "* 16", and the
// low digit is x - (x / base) * base.
fn mod(x, m) {
    return x - (x / m) * m
}

fn bcdDecode(x) {
    var value = 0
    var place = 1
    for var i in 0..4 {
        value += mod(x, 16) * place   // low nibble = one decimal digit
        x = x / 16                    // shift right 4 bits
        place *= 10
    }
    return value
}

fn bcdEncode(n) {
    var packed = 0
    var weight = 1
    for var i in 0..4 {
        packed += mod(n, 10) * weight // low decimal digit into its nibble
        n = n / 10
        weight *= 16                  // next nibble
    }
    return packed
}

fn bcdAdd(a, b) {
    return bcdEncode(mod(bcdDecode(a) + bcdDecode(b), 10000))
}

