    for (int n = (int)samples.size() - 1; n >= 0; n--) {
        long long acc = 0;
        for (int k = 0; k < (int)taps.size() && n - k >= 0; k++) acc += taps[k] * samples[n - k];
        long long mag = (llabs(acc) + 128) / 256;
        samples[n] = clamp(acc >= 0 ? mag : -mag, -32768LL, 32767LL);
    }
}

