    for n in (0..samples.len()).rev() {
        let acc: i64 = taps.iter().enumerate()
            .filter(|(k, _)| *k <= n)
            .map(|(k, t)| t * samples[n - k])
            .sum();
        let mag = (acc.abs() + 128) / 256;
        samples[n] = (if acc >= 0 { mag } else { -mag }).clamp(-32768, 32767);
    }
}

